17	/// Wait for inflight requests to drain, bounded by `timeout`. Returns the count
18	/// still inflight when the wait ends: `0` on a clean drain, `>0` if the timeout
19	/// fired (a stuck request must not wedge teardown). Shared by the NATS push and
20	/// TCP request planes.
21	async fn drain_inflight(
22	    inflight: Arc<AtomicU64>,
23	    notify: Arc<Notify>,
24	    endpoint_name: &str,
25	    timeout: Duration,
26	) -> u64 {
27	    let inflight_count = inflight.load(Ordering::SeqCst);
28	    if inflight_count == 0 {
29	        return 0;
30	    }
31	
32	    tracing::info!(
33	        endpoint_name,
34	        inflight_count,
35	        "Waiting for inflight requests to complete"
36	    );
37	
38	    let wait = async {
39	        while inflight.load(Ordering::SeqCst) > 0 {
40	            notify.notified().await;
41	        }
42	    };
43	
44	    match tokio::time::timeout(timeout, wait).await {
45	        Ok(()) => {
46	            tracing::info!(endpoint_name, "All inflight requests completed");
47	            0
48	        }
49	        Err(_) => {
50	            let remaining = inflight.load(Ordering::SeqCst);
51	            tracing::warn!(
52	                endpoint_name,
53	                timeout_secs = timeout.as_secs(),
54	                remaining,
55	                "Timed out waiting for inflight requests to drain; proceeding with shutdown"
56	            );
57	            remaining
58	        }
59	    }
60	}
61	
62	#[cfg(test)]
63	mod drain_tests {
64	    use super::*;
65	
66	    /// Drain returns within the bound even if the request never completes.
67	    #[tokio::test(start_paused = true)]
68	    async fn drain_inflight_is_bounded_when_request_never_completes() {
69	        let inflight = Arc::new(AtomicU64::new(1));
70	        let notify = Arc::new(Notify::new());
71	
72	        let remaining = tokio::time::timeout(
73	            Duration::from_secs(3600),
74	            drain_inflight(inflight, notify, "test-endpoint", Duration::from_secs(5)),
75	        )
76	        .await
77	        .expect("drain_inflight must be bounded; it hung past the outer guard");
78	
79	        assert_eq!(
80	            remaining, 1,
81	            "the stuck inflight request should still be counted as remaining"
82	        );
83	    }
84	
85	    /// A clean drain (request completes) returns 0 promptly.
86	    #[tokio::test(start_paused = true)]
87	    async fn drain_inflight_returns_zero_when_requests_complete() {
88	        let inflight = Arc::new(AtomicU64::new(1));
89	        let notify = Arc::new(Notify::new());
90	
91	        let inflight_clone = inflight.clone();
92	        let notify_clone = notify.clone();
93	        tokio::spawn(async move {
94	            inflight_clone.fetch_sub(1, Ordering::SeqCst);
95	            notify_clone.notify_one();
96	        });
97	
