372	/// TCP response message (acknowledgment or error)
373	///
374	/// Wire format:
375	/// - length: u32 (big-endian)
376	/// - data: bytes
377	#[derive(Debug, Clone, PartialEq, Eq)]
378	pub struct TcpResponseMessage {
379	    pub data: Bytes,
380	}
381	
382	impl TcpResponseMessage {
383	    pub fn new(data: Bytes) -> Self {
384	        Self { data }
385	    }
386	
387	    pub fn empty() -> Self {
388	        Self { data: Bytes::new() }
389	    }
390	
391	    /// Encode response to bytes (for backward compatibility)
392	    pub fn encode(&self) -> Result<Bytes, std::io::Error> {
393	        if self.data.len() > u32::MAX as usize {
394	            return Err(std::io::Error::new(
395	                std::io::ErrorKind::InvalidInput,
396	                format!("Response too large: {} bytes", self.data.len()),
397	            ));
398	        }
399	
400	        let mut buf = BytesMut::with_capacity(4 + self.data.len());
401	        buf.put_u32(self.data.len() as u32);
402	        buf.put_slice(&self.data);
403	        Ok(buf.freeze())
404	    }
405	
406	    /// Decode response from bytes (for backward compatibility, zero-copy when possible)
407	    pub fn decode(bytes: &Bytes) -> Result<Self, std::io::Error> {
408	        if bytes.len() < 4 {
409	            return Err(std::io::Error::new(
410	                std::io::ErrorKind::UnexpectedEof,
411	                "Not enough bytes for response length",
412	            ));
413	        }
414	
415	        // Read length (4 bytes)
416	        let len = u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]) as usize;
417	
418	        if bytes.len() < 4 + len {
419	            return Err(std::io::Error::new(
420	                std::io::ErrorKind::UnexpectedEof,
421	                format!(
422	                    "Not enough bytes for response: expected {}, got {}",
423	                    len,
424	                    bytes.len() - 4
425	                ),
426	            ));
427	        }
428	
429	        // Read data (zero-copy slice)
430	        let data = bytes.slice(4..4 + len);
431	
432	        Ok(Self { data })
433	    }
434	}
435	
436	const RESPONSE_LENGTH_WIDTH: usize = std::mem::size_of::<u32>();
437	
438	fn response_payload_limit(max_message_size: Option<usize>) -> usize {
439	    max_message_size
440	        .map(|max| max.saturating_sub(RESPONSE_LENGTH_WIDTH))
441	        .unwrap_or(u32::MAX as usize)
442	        .min(u32::MAX as usize)
443	}
444	
445	/// Codec for encoding/decoding TcpResponseMessage
446	/// Supports max_message_size enforcement
447	#[derive(Clone)]
448	pub struct TcpResponseCodec {
449	    decoder: LengthDelimitedCodec,
450	    reject_all_frames: bool,
451	}
452	
453	impl TcpResponseCodec {
454	    pub fn new(max_message_size: Option<usize>) -> Self {
455	        let reject_all_frames = max_message_size.is_some_and(|max| max < RESPONSE_LENGTH_WIDTH);
456	        let decoder = LengthDelimitedCodec::builder()
457	            .length_field_type::<u32>()
458	            .big_endian()
459	            .length_adjustment(RESPONSE_LENGTH_WIDTH as isize)
460	            .num_skip(0)
461	            .max_frame_length(response_payload_limit(max_message_size))
462	            .new_codec();
463	
464	        Self {
465	            decoder,
466	            reject_all_frames,
467	        }
468	    }
469	}
470	
471	impl Default for TcpResponseCodec {
472	    fn default() -> Self {
473	        Self::new(None)
474	    }
475	}
476	
477	impl Decoder for TcpResponseCodec {
478	    type Item = TcpResponseMessage;
479	    type Error = std::io::Error;
480	
481	    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {
482	        if self.reject_all_frames && src.len() >= RESPONSE_LENGTH_WIDTH {
483	            return Err(std::io::ErrorKind::InvalidData.into());
484	        }
485	
486	        self.decoder.decode(src).map(|frame| {
487	            frame.map(|mut frame| {
488	                frame.advance(RESPONSE_LENGTH_WIDTH);
489	                TcpResponseMessage {
490	                    data: frame.freeze(),
491	                }
492	            })
493	        })
494	    }
495	}
496	
497	impl Encoder<TcpResponseMessage> for TcpResponseCodec {
498	    type Error = std::io::Error;
499	
500	    fn encode(&mut self, item: TcpResponseMessage, dst: &mut BytesMut) -> Result<(), Self::Error> {
501	        if self.reject_all_frames {
502	            return Err(std::io::ErrorKind::InvalidInput.into());
503	        }
504	
505	        LengthDelimitedCodec::builder()
506	            .length_field_type::<u32>()
507	            .big_endian()
508	            .max_frame_length(self.decoder.max_frame_length())
509	            .new_codec()
510	            .encode(item.data, dst)
511	    }
512	}
