300	    /// Decode the wire envelope into its [`RequestControlMessage`] and the
301	    /// optional data payload, shared by every [`IngressDispatch`] shape:
302	    ///   - `HeaderAndData` → `(control, Some(data))` — the unary wire shape,
303	    ///     where the request body travels in the data half.
304	    ///   - `HeaderOnly` → `(control, None)` — the bidirectional wire shape,
305	    ///     where request frames flow on the request-stream socket instead.
306	    ///
307	    /// The caller decides whether its path expects the data payload. The
308	    /// deserialization and invalid-message error counters are incremented
309	    /// here so every shape reports them consistently.
310	    fn decode_control_message(
311	        &self,
312	        payload: Bytes,
313	    ) -> Result<(RequestControlMessage, Option<Bytes>), PipelineError> {
314	        let msg = TwoPartCodec::default()
315	            .decode_message(payload)?
316	            .into_message_type();
317	
318	        let (header, data) = match msg {
319	            TwoPartMessageType::HeaderAndData(header, data) => (header, Some(data)),
320	            TwoPartMessageType::HeaderOnly(header) => (header, None),
321	            _ => {
322	                if let Some(m) = self.metrics() {
323	                    m.error_counter
324	                        .with_label_values(&[work_handler::error_types::INVALID_MESSAGE])
325	                        .inc();
326	                }
327	                return Err(PipelineError::Generic(String::from(
328	                    "Unexpected message from work queue; expected a header-only or header-and-data TwoPartMessage",
329	                )));
330	            }
331	        };
332	
333	        let control_msg: RequestControlMessage =
334	            serde_json::from_slice(&header).map_err(|err| {
335	                if let Some(m) = self.metrics() {
336	                    m.error_counter
337	                        .with_label_values(&[work_handler::error_types::DESERIALIZATION])
338	                        .inc();
339	                }
340	                let json_str = String::from_utf8_lossy(&header);
341	                PipelineError::DeserializationError(format!(
342	                    "Failed deserializing to RequestControlMessage. err={err}, json_str={json_str}, header_len={}",
343	                    header.len(),
344	                ))
345	            })?;
346	
347	        Ok((control_msg, data))
348	    }
349	}
350	/// The output of [`IngressDispatch::parse_and_build_request`]: the typed
351	/// request the engine consumes, plus the bits of the on-wire control
352	/// message the shared handler needs after parsing (the response-stream
353	/// connection info and the frontend send timestamp).
354	struct ParsedRequest<Req> {
355	    request: Req,
356	    response_connection_info: ConnectionInfo,
357	    frontend_send_ts_ns: Option<u64>,
358	    payload_codec: RequestPlanePayloadCodec,
359	}
