361	/// Per-shape strategy for turning a raw payload into a typed engine
362	/// request. Captures the wire-shape divergence between the unary
363	/// (`HeaderAndData`) and bidirectional (`HeaderOnly` + dial-in for the
364	/// request stream) paths; everything else — metrics-guard, response stream
365	/// open, `segment.generate`, prologue, pump — lives in
366	/// [`Ingress::handle_payload_shared`] below.
367	#[async_trait]
368	trait IngressDispatch: Send + Sync {
369	    type Request: PipelineIO;
370	
371	    async fn parse_and_build_request(
372	        &self,
373	        payload: Bytes,
374	    ) -> Result<ParsedRequest<Self::Request>, PipelineError>;
375	}
