377	#[async_trait]
378	impl<T, U, Adapter> IngressDispatch for Ingress<SingleIn<T>, ManyOut<U>, Adapter>
379	where
380	    T: Data + for<'de> Deserialize<'de> + std::fmt::Debug,
381	    U: Data + std::fmt::Debug,
382	    Adapter: IngressRequestDecoder<T> + Send + Sync + 'static,
383	{
384	    type Request = SingleIn<T>;
385	
386	    async fn parse_and_build_request(
387	        &self,
388	        payload: Bytes,
389	    ) -> Result<ParsedRequest<SingleIn<T>>, PipelineError> {
390	        let (control_msg, data) = self.decode_control_message(payload)?;
391	
392	        // The unary path carries the request body in the data half; a
393	        // header-only envelope means the sender used the bidirectional shape.
394	        let data = data.ok_or_else(|| {
395	            if let Some(m) = self.metrics() {
396	                m.error_counter
397	                    .with_label_values(&[work_handler::error_types::INVALID_MESSAGE])
398	                    .inc();
399	            }
400	            PipelineError::Generic(String::from(
401	                "unary engine received a header-only envelope; expected a request payload",
402	            ))
403	        })?;
404	        let payload_codec = control_msg.payload_codec;
405	        let request_t: T = self
406	            .payload_adapter
407	            .decode_request(payload_codec, data)
408	            .await
409	            .inspect_err(|_| {
410	                if let Some(m) = self.metrics() {
411	                    m.error_counter
412	                        .with_label_values(&[work_handler::error_types::DESERIALIZATION])
413	                        .inc();
414	                }
415	            })?;
416	
417	        tracing::trace!(
418	            request_id = %control_msg.id,
419	            metadata_entries = control_msg.metadata.len(),
420	            "received control message"
421	        );
422	        tracing::trace!("received request: {:?}", request_t);
423	
424	        let request: context::Context<T> =
425	            Context::with_id_and_metadata(request_t, control_msg.id, control_msg.metadata);
426	
427	        Ok(ParsedRequest {
428	            request,
429	            response_connection_info: control_msg.connection_info,
430	            frontend_send_ts_ns: control_msg.frontend_send_ts_ns,
431	            payload_codec,
432	        })
433	    }
434	}
