437	impl<T, U, Adapter> IngressDispatch for Ingress<ManyIn<T>, ManyOut<U>, Adapter>
438	where
439	    T: Data + for<'de> Deserialize<'de> + std::fmt::Debug,
440	    U: Data + std::fmt::Debug,
441	    Adapter: IngressRequestDecoder<T> + Send + Sync + 'static,
442	{
443	    type Request = ManyIn<T>;
444	
445	    async fn parse_and_build_request(
446	        &self,
447	        payload: Bytes,
448	    ) -> Result<ParsedRequest<ManyIn<T>>, PipelineError> {
449	        let (control_msg, data) = self.decode_control_message(payload)?;
450	
451	        // Bidirectional envelopes are header-only — all request frames
452	        // (including the first) flow on the request-stream socket once it's
453	        // dialed in. A data payload means the sender used the unary wire
454	        // shape; reject it.
455	        if data.is_some() {
456	            if let Some(m) = self.metrics() {
457	                m.error_counter
458	                    .with_label_values(&[work_handler::error_types::INVALID_MESSAGE])
459	                    .inc();
460	            }
461	            return Err(PipelineError::Generic(String::from(
462	                "bidirectional engine received a non-header-only envelope",
463	            )));
464	        }
465	
466	        if !matches!(control_msg.request_type, RequestType::ManyIn) {
467	            if let Some(m) = self.metrics() {
468	                m.error_counter
469	                    .with_label_values(&[work_handler::error_types::INVALID_MESSAGE])
470	                    .inc();
471	            }
472	            return Err(PipelineError::Generic(String::from(
473	                "bidirectional engine received a non-ManyIn request envelope",
474	            )));
475	        }
476	
477	        let req_stream_conn_info = control_msg
478	            .request_stream_connection_info
479	            .clone()
480	            .ok_or_else(|| {
481	                PipelineError::Generic(String::from(
482	                    "bidirectional control message missing request_stream_connection_info",
483	                ))
484	            })?;
485	
486	        let request_context: context::Context<()> = context::Context::with_id_and_metadata(
487	            (),
488	            control_msg.id.clone(),
489	            control_msg.metadata.clone(),
490	        );
491	        let payload_codec = control_msg.payload_codec;
492	        let context_arc: Arc<dyn AsyncEngineContext> = request_context.context();
493	
494	        // Open the request stream (upstream → worker) up front. The shared
495	        // handler opens the response stream uniformly after we return. If
496	        // response-stream open subsequently fails, the forwarder task
497	        // spawned below exits cleanly when `frame_tx.send` observes the
498	        // dropped `frame_rx`.
499	        let request_stream_recv = tcp::client::TcpClient::create_request_stream(
500	            context_arc.clone(),
501	            req_stream_conn_info,
502	            None,
503	        )
504	        .await
505	        .map_err(|e| {
506	            if let Some(m) = self.metrics() {
507	                m.error_counter
508	                    .with_label_values(&[work_handler::error_types::RESPONSE_STREAM])
509	                    .inc();
510	            }
511	            PipelineError::Generic(format!("Failed to create request stream: {e}"))
512	        })?;
513	
514	        // Forwarder: deserialize raw bytes off the request socket into `T`
515	        // and feed the engine's `ManyIn<T>` input. Every request frame
516	        // (including the first) flows over this socket — the envelope is
517	        // header-only.
518	        let (frame_tx, frame_rx) = tokio::sync::mpsc::channel::<T>(8);
519	        let forwarder_ctx = context_arc.clone();
520	        let payload_adapter = self.payload_adapter.clone();
521	        tokio::spawn(async move {
522	            let mut rx = request_stream_recv.rx;
523	            while let Some(bytes) = rx.recv().await {
524	                // Stop forwarding on either kill or soft-stop, matching the
525	                // send-side `spawn_request_stream_forwarder`. Without the
526	                // `stopped()` check, a `stop_generating()` would leave this
527	                // task pumping frames into a channel the engine has abandoned.
528	                if forwarder_ctx.is_killed() || forwarder_ctx.is_stopped() {
529	                    break;
530	                }
531	                match payload_adapter.decode_request(payload_codec, bytes).await {
532	                    Ok(item) => {
533	                        if frame_tx.send(item).await.is_err() {
534	                            tracing::debug!(
535	                                "engine consumer dropped; bidirectional input forwarder exiting"
536	                            );
537	                            break;
538	                        }
539	                    }
540	                    Err(e) => {
541	                        tracing::error!(
542	                            error = %e,
543	                            codec = payload_codec.name(),
544	                            "failed to deserialize bidirectional request frame; killing context"
545	                        );
546	                        forwarder_ctx.kill();
547	                        break;
548	                    }
549	                }
550	            }
551	        });
552	
553	        let input_stream: crate::engine::DataStream<T> =
554	            Box::pin(tokio_stream::wrappers::ReceiverStream::new(frame_rx));
555	        let request: ManyIn<T> = request_context.map(|_| RequestStream::new(input_stream));
556	
557	        Ok(ParsedRequest {
558	            request,
559	            response_connection_info: control_msg.connection_info,
560	            frontend_send_ts_ns: control_msg.frontend_send_ts_ns,
561	            payload_codec,
562	        })
563	    }
564	}
