566	impl<Req, U, Adapter> Ingress<Req, ManyOut<U>, Adapter>
567	where
568	    Req: PipelineIO + Sync,
569	    U: Data + std::fmt::Debug,
570	    Adapter: IngressResponseEncoder<U> + Send + Sync + 'static,
571	{
572	    /// Shared body of `PushWorkHandler::handle_payload` for every
573	    /// `Ingress<Req, ManyOut<U>>` shape that has an [`IngressDispatch`]
574	    /// impl. Sets up the inflight metrics guard, calls
575	    /// `parse_and_build_request` for the wire-shape-specific request
576	    /// building, opens the response stream uniformly, dispatches via
577	    /// the engine, sends the prologue, and pumps the response through
578	    /// [`Self::pump_response_stream`].
579	    async fn handle_payload_shared(
580	        &self,
581	        payload: Bytes,
582	        request_id: Option<String>,
583	    ) -> Result<(), PipelineError>
584	    where
585	        Self: IngressDispatch<Request = Req>,
586	    {
587	        let t2_wallclock_ns = std::time::SystemTime::now()
588	            .duration_since(std::time::UNIX_EPOCH)
589	            .unwrap_or_default()
590	            .as_nanos() as u64;
591	        let start_time = std::time::Instant::now();
592	
593	        // Increment inflight and ensure it's decremented on all exits via RAII guard
594	        let _inflight_guard = self.metrics().map(|m| {
595	            m.request_counter.inc();
596	            m.inflight_requests.inc();
597	            m.request_bytes.inc_by(payload.len() as u64);
598	            if let Some(rid) = &request_id {
599	                tracing::info!(request_id = %rid, "request received");
600	            }
601	            RequestMetricsGuard {
602	                inflight_requests: m.inflight_requests.clone(),
603	                request_duration: m.request_duration.clone(),
604	                start_time,
605	                request_id: request_id.clone(),
606	            }
607	        });
608	
609	        let ParsedRequest {
610	            request,
611	            response_connection_info,
612	            frontend_send_ts_ns,
613	            payload_codec,
614	        } = self.parse_and_build_request(payload).await?;
615	
616	        // Compute network transit time (T2 - T1) using cross-process wall-clock timestamps
617	        if let Some(t1_ns) = frontend_send_ts_ns {
618	            let transit_ns = t2_wallclock_ns.saturating_sub(t1_ns);
619	            WORK_HANDLER_NETWORK_TRANSIT_SECONDS.observe(transit_ns as f64 / 1_000_000_000.0);
620	        }
621	
622	        // todo - eventually have a handler class which will returned an abstracted object, but for now,
623	        // we only support tcp here, so we can just unwrap the connection info
624	        tracing::trace!("creating tcp response stream");
625	        let mut publisher = tcp::client::TcpClient::create_response_stream(
626	            request.context(),
627	            response_connection_info,
628	            self.metrics().map(|m| m.cancellation_total.clone()),
629	        )
630	        .await
631	        .map_err(|e| {
632	            if let Some(m) = self.metrics() {
633	                m.error_counter
634	                    .with_label_values(&[work_handler::error_types::RESPONSE_STREAM])
635	                    .inc();
636	            }
637	            PipelineError::Generic(format!("Failed to create response stream: {e}"))
638	        })?;
639	
640	        tracing::trace!("calling generate");
641	        let stream = self
642	            .segment
643	            .get()
644	            .expect("segment not set")
645	            .generate(request)
646	            .await
647	            .map_err(|e| {
648	                if let Some(m) = self.metrics() {
649	                    m.error_counter
650	                        .with_label_values(&[work_handler::error_types::GENERATE])
651	                        .inc();
652	                }
653	                PipelineError::GenerateError(e)
654	            });
655	
656	        // the prolouge is sent to the client to indicate that the stream is ready to receive data
657	        // or if the generate call failed, the error is sent to the client
658	        let stream = match stream {
659	            Ok(stream) => {
660	                tracing::trace!("Successfully generated response stream; sending prologue");
661	                let _result = publisher.send_prologue(None).await;
662	                WORK_HANDLER_TIME_TO_FIRST_RESPONSE_SECONDS
663	                    .observe(start_time.elapsed().as_secs_f64());
664	                stream
665	            }
666	            Err(e) => {
667	                let error_string = e.to_string();
668	
669	                #[cfg(debug_assertions)]
670	                {
671	                    tracing::debug!(
672	                        "Failed to generate response stream (with debug backtrace): {:?}",
673	                        e
674	                    );
675	                }
676	                #[cfg(not(debug_assertions))]
677	                {
678	                    tracing::error!("Failed to generate response stream: {error_string}");
679	                }
680	
681	                let _result = publisher.send_prologue(Some(error_string)).await;
682	                Err(e)?
683	            }
684	        };
685	
686	        self.pump_response_stream(stream, &publisher, payload_codec)
687	            .await;
688	
689	        // Ensure the metrics guard is not dropped until the end of the function.
690	        // Drop fires "request completed" log via RAII.
691	        drop(_inflight_guard);
692	
693	        Ok(())
694	    }
695	}
