762	mod tests {
763	    use super::*;
764	    use crate::pipeline::network::{Ingress, RequestPlanePayloadCodec, StreamSender};
765	    use crate::pipeline::{Context, ManyOut, ResponseStream, SingleIn};
766	    use crate::protocols::annotated::Annotated;
767	    use futures::stream;
768	    use prometheus::{Histogram, HistogramOpts, IntCounter, IntCounterVec, IntGauge, Opts};
769	
770	    type TestRequest = serde_json::Value;
771	    type TestResponse = Annotated<serde_json::Value>;
772	    type TestIngress = Ingress<SingleIn<TestRequest>, ManyOut<TestResponse>>;
773	
774	    /// Standalone metrics, not bound to an `Endpoint`, so the test needs no DRT.
775	    fn test_metrics() -> WorkHandlerMetrics {
776	        WorkHandlerMetrics::new(
777	            IntCounter::with_opts(Opts::new("requests_total", "t")).unwrap(),
778	            Histogram::with_opts(HistogramOpts::new("request_duration_seconds", "t")).unwrap(),
779	            IntGauge::with_opts(Opts::new("inflight_requests", "t")).unwrap(),
780	            IntCounter::with_opts(Opts::new("request_bytes_total", "t")).unwrap(),
781	            IntCounter::with_opts(Opts::new("response_bytes_total", "t")).unwrap(),
782	            IntCounterVec::new(
783	                Opts::new(work_handler::ERRORS_TOTAL, "t"),
784	                &[work_handler::ERROR_TYPE_LABEL],
785	            )
786	            .unwrap(),
787	            IntCounter::with_opts(Opts::new("cancellation_total", "t")).unwrap(),
788	        )
789	    }
790	
791	    /// Which half of the teardown race a given run exercises.
792	    #[derive(Clone, Copy, Debug)]
793	    enum Teardown {
794	        /// Frontend sent `ControlMessage::Stop`; the control reader called
795	        /// `context.stop()` (see `tcp/client.rs`).
796	        Stop,
797	        /// Frontend sent `ControlMessage::Kill`; the control reader called
798	        /// `context.kill()`.
799	        Kill,
800	        /// The response-stream reader hit a TCP read error and called
801	        /// `context.kill()` (`tcp/client.rs`, "tcp stream read error").
802	        /// Indistinguishable from `Kill` at the context level, which is
803	        /// exactly why `is_stopped()` alone is too coarse a guard.
804	        ConnectionReadError,
805	        /// The transport died with the client still attached and the context
806	        /// live — a genuine failure that must stay classified as an error.
807	        TransportOnly,
808	    }
809	
810	    /// Drive `pump_response_stream` through the client-teardown ordering:
811	    /// the engine emits `content_frames` chunks, then the upstream reader goes
812	    /// away (mirroring `handle_writer` exiting on `context.stopped()`) while the
813	    /// trailing `complete_final` frame is still unsent.
814	    ///
815	    /// Returns (publish_final count, publish_response count).
816	    async fn run_teardown_race(content_frames: usize, teardown: Teardown) -> (u64, u64) {
817	        let ingress = TestIngress::new();
818	        let metrics = Arc::new(test_metrics());
819	        ingress
820	            .metrics
821	            .set(metrics.clone())
822	            .expect("metrics already set");
823	
824	        // Capacity covers every content frame, so a send only fails once the
825	        // receiver is gone — never merely because the channel is full.
826	        let (tx, mut rx) = tokio::sync::mpsc::channel(content_frames + 8);
827	        let publisher = StreamSender { tx, prologue: None };
828	
829	        let ctx = Context::new(serde_json::json!({}));
830	        let engine_ctx = ctx.context();
831	
832	        // The stream yields its content, then parks until the test has torn the
833	        // receiver down. Ending after the gate (rather than on a timer) is what
834	        // makes the race deterministic.
835	        let (gate_tx, gate_rx) = tokio::sync::oneshot::channel::<()>();
836	        let content: Vec<TestResponse> = (0..content_frames)
837	            .map(|i| Annotated::from_data(serde_json::json!({ "token": i })))
838	            .collect();
839	        let tail = stream::unfold(Some(gate_rx), |state| async move {
840	            // Awaiting then yielding `None` ends the stream, so
841	            // `send_complete_final` stays true and the final frame is attempted.
842	            let gate = state?;
843	            let _ = gate.await;
844	            None
845	        });
846	        let response_stream: ManyOut<TestResponse> = ResponseStream::new(
847	            Box::pin(stream::iter(content).chain(tail)),
848	            engine_ctx.clone(),
849	        );
850	
851	        let pump = tokio::spawn({
852	            let ingress = ingress.clone();
853	            async move {
854	                ingress
855	                    .pump_response_stream(
856	                        response_stream,
857	                        &publisher,
858	                        RequestPlanePayloadCodec::Json,
859	                    )
860	                    .await;
861	            }
862	        });
863	
864	        // Drain the content frames so the pump is past the per-frame branch.
865	        for _ in 0..content_frames {
866	            rx.recv().await.expect("content frame");
867	        }
868	
869	        // Now reproduce the teardown: the frontend has everything it needs and
870	        // drops the request, which kills the worker's writer task.
871	        match teardown {
872	            Teardown::Stop => engine_ctx.stop(),
873	            Teardown::Kill | Teardown::ConnectionReadError => engine_ctx.kill(),
874	            Teardown::TransportOnly => {}
875	        }
876	        drop(rx);
877	        let _ = gate_tx.send(());
878	
879	        pump.await.expect("pump task panicked");
880	
881	        let errors = &metrics.error_counter;
882	        (
883	            errors
884	                .with_label_values(&[work_handler::error_types::PUBLISH_FINAL])
885	                .get(),
886	            errors
887	                .with_label_values(&[work_handler::error_types::PUBLISH_RESPONSE])
888	                .get(),
889	        )
890	    }
891	
892	    /// Losing the `complete_final` send to a client that has already
893	    /// torn down is not a worker error. The per-frame branch already makes this
894	    /// distinction; the final-marker branch must make it too.
895	    #[tokio::test]
896	    async fn test_publish_final_race_with_stopped_context_is_not_an_error() {
897	        let (publish_final, publish_response) = run_teardown_race(3, Teardown::Stop).await;
898	        assert_eq!(
899	            publish_final, 0,
900	            "complete_final lost to a stopped context must not count as an error"
901	        );
902	        assert_eq!(
903	            publish_response, 0,
904	            "content frames were all delivered before teardown"
905	        );
906	    }
907	
908	    /// A killed context must stay a counted error. `is_stopped()` is
909	    /// `state != Live`, so it is true after `kill()` as well — but the
910	    /// response-stream reader kills the context on a TCP read error, so
911	    /// suppressing on `is_stopped()` alone would hide real connection
912	    /// failures from the very counter meant to surface them.
913	    #[tokio::test]
914	    async fn test_publish_final_with_killed_context_is_still_an_error() {
915	        let (publish_final, _) = run_teardown_race(3, Teardown::Kill).await;
916	        assert_eq!(
917	            publish_final, 1,
918	            "a killed context is not a graceful teardown and must still be counted"
919	        );
920	    }
921	
922	    /// The concrete regression: `tcp/client.rs` calls `context.kill()` on a TCP
923	    /// read error ("tcp stream read error, closing connection"). That path must
924	    /// remain visible in `dynamo_component_errors_total`.
925	    #[tokio::test]
926	    async fn test_publish_final_after_connection_read_error_is_still_an_error() {
927	        let (publish_final, _) = run_teardown_race(3, Teardown::ConnectionReadError).await;
928	        assert_eq!(
929	            publish_final, 1,
930	            "a dropped connection must not be silently reclassified as a benign teardown"
931	        );
932	    }
933	
934	    /// Guards against suppressing too much: with the context still live, a failed
935	    /// `complete_final` is a real transport failure and must still be counted.
936	    #[tokio::test]
937	    async fn test_publish_final_failure_without_stop_is_still_an_error() {
938	        let (publish_final, _) = run_teardown_race(3, Teardown::TransportOnly).await;
939	        assert_eq!(
940	            publish_final, 1,
941	            "a genuine complete_final failure must still be counted"
942	        );
943	    }
944	
945	    /// The marker itself is the transport-level end-of-stream signal that
946	    /// non-chat consumers (KV-router worker index queries, disaggregated
947	    /// prefill→decode) rely on to tell a clean end from a truncated one. The
948	    /// classification change must not disturb the clean path: every content
949	    /// frame plus a `complete_final: true` frame still goes out, and nothing is
950	    /// counted as an error.
951	    #[tokio::test]
952	    async fn test_complete_final_marker_still_sent_on_clean_stream() {
953	        let ingress = TestIngress::new();
954	        let metrics = Arc::new(test_metrics());
955	        ingress.metrics.set(metrics.clone()).unwrap();
956	
957	        let content_frames = 3;
958	        let (tx, mut rx) = tokio::sync::mpsc::channel(content_frames + 8);
959	        let publisher = StreamSender { tx, prologue: None };
960	
961	        let ctx = Context::new(serde_json::json!({}));
962	        let content: Vec<TestResponse> = (0..content_frames)
963	            .map(|i| Annotated::from_data(serde_json::json!({ "token": i })))
964	            .collect();
965	        let response_stream: ManyOut<TestResponse> =
966	            ResponseStream::new(Box::pin(stream::iter(content)), ctx.context());
967	
968	        ingress
969	            .pump_response_stream(response_stream, &publisher, RequestPlanePayloadCodec::Json)
970	            .await;
971	        drop(publisher);
972	
973	        let mut frames = Vec::new();
974	        while let Some(msg) = rx.recv().await {
975	            let (_header, data) = msg.into_parts();
976	            frames.push(serde_json::from_slice::<serde_json::Value>(&data).unwrap());
977	        }
978	
979	        assert_eq!(
980	            frames.len(),
981	            content_frames + 1,
982	            "expected every content frame plus the trailing marker"
983	        );
984	        for (i, frame) in frames.iter().take(content_frames).enumerate() {
985	            assert_eq!(frame["complete_final"], false, "content frame {i}");
986	        }
987	        assert_eq!(
988	            frames[content_frames]["complete_final"], true,
989	            "trailing frame must carry the end-of-stream marker"
990	        );
991	
992	        let errors = &metrics.error_counter;
993	        assert_eq!(
994	            errors
995	                .with_label_values(&[work_handler::error_types::PUBLISH_FINAL])
996	                .get(),
997	            0
998	        );
999	        assert_eq!(
1000	            errors
1001	                .with_label_values(&[work_handler::error_types::PUBLISH_RESPONSE])
1002	                .get(),
1003	            0
1004	        );
1005	    }
1006	}
