351	/// Watch discovery for instance removals and cancel pending response-stream
352	/// registrations on the removed instance, unblocking queued requests with
353	/// a migratable `Disconnected` error. Uses raw `list_and_watch` events
354	/// (not a coalesced snapshot diff) so a rapid remove→re-add of the same
355	/// identity is not silently swallowed. Keyed by full `EndpointInstanceId`.
356	fn spawn_instance_removal_watcher<T, U>(
357	    endpoint: Endpoint,
358	    dispatch: Arc<dyn StreamingDispatch<T, U>>,
359	    cancel_token: tokio_util::sync::CancellationToken,
360	) where
361	    T: Data + Serialize + 'static,
362	    U: Data + for<'de> Deserialize<'de> + MaybeError + 'static,
363	{
364	    use crate::discovery::{
365	        DiscoveryEvent, DiscoveryInstance, DiscoveryInstanceId, DiscoveryQuery,
366	    };
367	    use tokio_stream::StreamExt as _;
368	
369	    // One watcher per endpoint: if one is already running, skip.
370	    let guard = ENDPOINT_WATCHER_ACTIVE.get_or_init(dashmap::DashMap::new);
371	    let endpoint_id = endpoint.id();
372	    if guard.insert(endpoint_id.clone(), ()).is_some() {
373	        tracing::debug!(
374	            ?endpoint_id,
375	            "Instance removal watcher already running for this endpoint, skipping"
376	        );
377	        return;
378	    }
379	
380	    let endpoint_name = endpoint.name().to_string();
381	
382	    tokio::spawn(async move {
383	        // Release on every exit path (including panic); a leaked entry
384	        // silently disables removal cancellation until process restart.
385	        struct GuardRelease(EndpointId);
386	        impl Drop for GuardRelease {
387	            fn drop(&mut self) {
388	                if let Some(map) = ENDPOINT_WATCHER_ACTIVE.get() {
389	                    map.remove(&self.0);
390	                }
391	            }
392	        }
393	        let _release = GuardRelease(endpoint_id);
394	
395	        let namespace = endpoint.component().namespace().name();
396	        let component = endpoint.component().name().to_string();
397	
398	        // Reconnect on transient discovery failure; cancel-aware backoff.
399	        const RECONNECT_BACKOFF: std::time::Duration = std::time::Duration::from_secs(5);
400	        'reconnect: loop {
401	            let query = DiscoveryQuery::Endpoint {
402	                namespace: namespace.clone(),
403	                component: component.clone(),
404	                endpoint: endpoint_name.clone(),
405	            };
406	
407	            let mut stream = match endpoint.drt().discovery().list_and_watch(query, None).await {
408	                Ok(s) => s,
409	                Err(e) => {
410	                    tracing::warn!(
411	                        endpoint = %endpoint_name,
412	                        "Failed to start instance removal watcher (will retry): {e}"
413	                    );
414	                    tokio::select! {
415	                        _ = tokio::time::sleep(RECONNECT_BACKOFF) => continue 'reconnect,
416	                        _ = cancel_token.cancelled() => break 'reconnect,
417	                    }
418	                }
419	            };
420	
421	            loop {
422	                tokio::select! {
423	                    event = stream.next() => {
424	                        match event {
425	                            Some(Ok(DiscoveryEvent::Removed(id))) => {
426	                                if let DiscoveryInstanceId::Endpoint(eid) = &id {
427	                                    dispatch.on_instance_removed(eid).await;
428	                                }
429	                            }
430	                            Some(Ok(DiscoveryEvent::Added(DiscoveryInstance::Endpoint(inst)))) => {
431	                                let eid: EndpointInstanceId = inst.endpoint_instance_id();
432	                                dispatch.on_instance_added(&eid).await;
433	                            }
434	                            Some(Ok(_)) => {}
435	                            Some(Err(e)) => {
436	                                tracing::warn!(
437	                                    endpoint = %endpoint_name,
438	                                    "Instance removal watcher stream error: {e}"
439	                                );
440	                            }
441	                            None => {
442	                                tracing::warn!(
443	                                    endpoint = %endpoint_name,
444	                                    "Instance removal watcher stream ended; reconnecting"
445	                                );
446	                                continue 'reconnect;
447	                            }
448	                        }
449	                    }
450	                    _ = cancel_token.cancelled() => {
451	                        break 'reconnect;
452	                    }
453	                }
454	            }
455	        }
456	
457	        tracing::debug!(endpoint = %endpoint_name, "Instance removal watcher exiting");
458	    });
459	}
