461	/// Watch discovery removals for cache-aware routers and drop stale worker cache entries.
462	fn spawn_multimodal_cache_cleanup_watcher(
463	    endpoint: Endpoint,
464	    indexer: Arc<dyn MultimodalCacheIndex>,
