469	
470	    let guard = ENDPOINT_CACHE_INDEXER_WATCHER_ACTIVE.get_or_init(dashmap::DashMap::new);
471	    let watcher_id = RuntimeEndpointId::for_endpoint(&endpoint);
472	    if guard.insert(watcher_id.clone(), ()).is_some() {
473	        tracing::debug!(
474	            connection_id = watcher_id.connection_id,
475	            ?watcher_id.endpoint_id,
476	            "Multimodal cache cleanup watcher already running for this runtime endpoint, skipping"
477	        );
