481	    let endpoint_name = endpoint.name().to_string();
482	    let namespace = endpoint.component().namespace().name();
483	    let component = endpoint.component().name().to_string();
484	
485	    tokio::spawn(async move {
486	        struct GuardRelease(RuntimeEndpointId);
487	        impl Drop for GuardRelease {
488	            fn drop(&mut self) {
489	                if let Some(map) = ENDPOINT_CACHE_INDEXER_WATCHER_ACTIVE.get() {
490	                    map.remove(&self.0);
491	                }
492	            }
493	        }
494	        let _release = GuardRelease(watcher_id);
495	
496	        const RECONNECT_BACKOFF: std::time::Duration = std::time::Duration::from_secs(5);
497	        'reconnect: loop {
498	            let query = DiscoveryQuery::Endpoint {
499	                namespace: namespace.clone(),
500	                component: component.clone(),
501	                endpoint: endpoint_name.clone(),
502	            };
503	
504	            let mut stream = match endpoint.drt().discovery().list_and_watch(query, None).await {
505	                Ok(stream) => stream,
506	                Err(error) => {
507	                    tracing::warn!(
508	                        endpoint = %endpoint_name,
509	                        "Failed to start multimodal cache cleanup watcher (will retry): {error}"
510	                    );
511	                    tokio::select! {
512	                        _ = tokio::time::sleep(RECONNECT_BACKOFF) => continue 'reconnect,
513	                        _ = cancel_token.cancelled() => break 'reconnect,
514	                    }
515	                }
516	            };
517	
518	            loop {
519	                tokio::select! {
520	                    event = stream.next() => {
521	                        match event {
522	                            Some(Ok(DiscoveryEvent::Removed(DiscoveryInstanceId::Endpoint(eid)))) => {
523	                                indexer.remove_worker(eid.instance_id);
524	                            }
525	                            Some(Ok(_)) => {}
526	                            Some(Err(error)) => {
527	                                tracing::warn!(
528	                                    endpoint = %endpoint_name,
529	                                    "Multimodal cache cleanup watcher stream error: {error}"
530	                                );
531	                                continue 'reconnect;
532	                            }
533	                            None => {
534	                                tracing::warn!(
535	                                    endpoint = %endpoint_name,
536	                                    "Multimodal cache cleanup watcher stream ended; reconnecting"
537	                                );
538	                                continue 'reconnect;
539	                            }
540	                        }
541	                    }
542	                    _ = cancel_token.cancelled() => break 'reconnect,
543	                }
544	            }
545	        }
546	
547	        tracing::debug!(endpoint = %endpoint_name, "Multimodal cache cleanup watcher exiting");
548	    });
549	}
