723	    /// `ResourceExhausted` when workers are routable but all overloaded;
724	    /// `Unavailable` when no routable workers exist.
725	    fn empty_free_pool_error(&self, routing_instances: &RoutingInstances) -> anyhow::Error {
726	        if !routing_instances.routable_ids().is_empty() {
727	            let cause = PipelineError::ServiceOverloaded(
728	                "All workers are busy, please retry later".to_string(),
729	            );
730	            return DynamoError::builder()
731	                .error_type(ErrorType::ResourceExhausted)
732	                .message("All workers are busy, please retry later")
733	                .cause(cause)
734	                .build()
735	                .into();
736	        }
737	        DynamoError::builder()
738	            .error_type(ErrorType::Unavailable)
739	            .message(format!(
740	                "No workers available for endpoint {}",
741	                self.client.endpoint.id()
742	            ))
743	            .build()
744	            .into()
745	    }
