756	    fn select_untracked_worker(&self, picker: &RoutePicker) -> anyhow::Result<(u64, usize)> {
757	        let routing_instances = self.client.routing_instances();
758	        let candidates = routing_instances.free_ids();
759	        let decision = picker
760	            .select(
761	                CandidateView::Workers(candidates),
762	                RouteContext::default(),
763	                |_| 0,
764	            )
765	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
766	        Ok((decision.target.worker_id, candidates.len()))
