794	    /// Select a DeviceAware worker while leaving request-lifecycle cleanup to
795	    /// the routing host. Request and device metadata is prepared before the
796	    /// occupancy admission lock is acquired.
797	    pub fn select_device_aware_and_reserve(
798	        &self,
799	        request: &T,
800	        pinned_worker: Option<u64>,
801	    ) -> anyhow::Result<DeviceAwareSelection> {
802	        anyhow::ensure!(
803	            self.router_mode == RouterMode::DeviceAwareWeighted,
804	            "{:?} routing is not DeviceAwareWeighted",
805	            self.router_mode
806	        );
807	
808	        let state = self.occupancy_state()?;
809	        if let Some(worker_id) = pinned_worker {
810	            self.ensure_routable(worker_id)?;
811	            let selection = self.device_aware_candidates(request, &[worker_id]);
812	            let is_cpu = selection
813	                .candidates
814	                .first()
815	                .is_some_and(|candidate| candidate.device == RouteDevice::Cpu);
816	            let reservation = state.reserve(worker_id);
817	            let load = reservation.load();
818	            return Ok(DeviceAwareSelection {
819	                worker_id,
820	                candidate_count: 1,
821	                load,
822	                is_cpu,
823	                embedding_cache_hit: selection.embedding_cache_hit,
824	                request_cache_keys: selection.request_cache_keys,
825	                reservation: Some(reservation),
826	            });
827	        }
828	
829	        let routing_instances = self.client.routing_instances();
830	        let instance_ids = routing_instances.free_ids();
831	        if instance_ids.is_empty() {
832	            return Err(self.empty_free_pool_error(&routing_instances));
833	        }
834	        let selection = self.device_aware_candidates(request, instance_ids);
835	        let (decision, counter) = state
836	            .select_and_admit(
837	                self.picker()?,
838	                CandidateView::DeviceAware(&selection.candidates),
839	                selection.context,
840	            )
841	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
842	        let worker_id = decision.target.worker_id;
843	        let is_cpu = selection.candidates.iter().any(|candidate| {
844	            candidate.target.worker_id == worker_id && candidate.device == RouteDevice::Cpu
845	        });
846	        let reservation = counter
847	            .map(|counter| OccupancyReservation::from_counter(state.clone(), worker_id, counter));
848	
849	        Ok(DeviceAwareSelection {
850	            worker_id,
851	            candidate_count: selection.candidates.len(),
852	            load: state.load(worker_id),
853	            is_cpu,
854	            embedding_cache_hit: selection.embedding_cache_hit,
855	            request_cache_keys: selection.request_cache_keys,
856	            reservation,
857	        })
858	    }
