1065	    async fn direct_prepared_with_fallback<M, F>(
1066	        &self,
1067	        instance_id: u64,
1068	        request: SingleIn<T>,
1069	        fallback: TransportFallback<'_>,
1070	        prepare: F,
1071	    ) -> anyhow::Result<(M, ManyOut<U>)>
1072	    where
1073	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1074	    {
