1085	                .client
1086	                .routing_instances()
1087	                .free_ids()
1088	                .iter()
1089	                .copied()
1090	                .any(|candidate| {
1091	                    candidate != instance_id
1092	                        && match fallback {
1093	                            TransportFallback::Allow => true,
1094	                            TransportFallback::Deny => false,
1095	                            TransportFallback::Within(allowed) => allowed.contains(&candidate),
1096	                        }
1097	                });
1098	            if !fallback_is_available {
1099	                self.ensure_discovered_for_dispatch(instance_id)?;
1100	            }
1101	        }
1102	        let ((metadata, resolved_instance_id), response_stream) = self
1103	            .generate_with_fault_detection_prepared(
1104	                instance_id,
1105	                request,
1106	                fallback,
1107	                |request, resolved_instance_id| {
1108	                    prepare(request, resolved_instance_id)
1109	                        .map(|metadata| (metadata, resolved_instance_id))
1110	                },
1111	            )
1112	            .await?;
1113	        tracing::info!(
1114	            router_mode = self.router_mode.telemetry_label(),
1115	            worker_id = resolved_instance_id,
1116	            "Selected worker"
1117	        );
