1233	    /// Issue a request using device-aware weighted routing.
1234	    ///
1235	    /// Instances are partitioned by device type (CPU vs non-CPU), then the router
1236	    /// applies a budget policy and selects the least-loaded instance within the
1237	    /// chosen group.
1238	    ///
1239	    /// If only one device class exists (all CPU or all non-CPU), this naturally
1240	    /// degenerates to least-loaded routing over the available instances.
1241	    pub async fn device_aware_weighted(&self, request: SingleIn<T>) -> anyhow::Result<ManyOut<U>> {
1242	        self.device_aware_weighted_prepared(request, |_, _| Ok(()))
1243	            .await
1244	            .map(|(_, stream)| stream)
1245	    }
1246	
1247	    async fn device_aware_weighted_prepared<M, F>(
1248	        &self,
1249	        request: SingleIn<T>,
1250	        prepare: F,
1251	    ) -> anyhow::Result<(M, ManyOut<U>)>
1252	    where
1253	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1254	    {
1255	        let state = self.occupancy_state()?;
1256	        let routing_instances = self.client.routing_instances();
1257	        let instance_ids = routing_instances.free_ids();
1258	
1259	        if instance_ids.is_empty() {
1260	            return Err(self.empty_free_pool_error(&routing_instances));
1261	        }
1262	
1263	        // Apply a unified policy for all endpoints.
1264	        let endpoint_id = self.client.endpoint.id();
1265	
1266	        let selection = self.device_aware_candidates(request.content(), instance_ids);
1267	
1268	        // Only full cache hits bypass weighted accounting; partial hits still follow the
1269	        // device-aware ratio because some image encoding remains for this request.
1270	        let (decision, counter) = state
1271	            .select_and_admit(
1272	                self.picker()?,
1273	                CandidateView::DeviceAware(&selection.candidates),
1274	                selection.context,
1275	            )
1276	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
1277	        let instance_id = decision.target.worker_id;
1278	        let permit = counter
1279	            .map(|counter| OccupancyPermit::from_counter(state.clone(), instance_id, counter));
1280	        let is_cpu = selection.candidates.iter().any(|candidate| {
1281	            candidate.target.worker_id == instance_id && candidate.device == RouteDevice::Cpu
1282	        });
1283	        tracing::info!(
1284	            router_mode = "device-aware-weighted",
1285	            worker_id = instance_id,
1286	            candidate_count = selection.candidates.len(),
1287	            load = state.load(instance_id),
1288	            endpoint = %endpoint_id,
1289	            is_cpu,
1290	            embedding_cache_hit = selection.embedding_cache_hit,
1291	            request_cache_keys = selection.request_cache_keys,
1292	            "Selected worker"
1293	        );
1294	
1295	        self.dispatch_selected(instance_id, request, permit, prepare)
1296	            .await
1297	    }
