1299	    fn device_aware_candidates(&self, request: &T, instance_ids: &[u64]) -> DeviceAwareCandidates {
1300	        let device_type_map = self
1301	            .client
1302	            .instances()
1303	            .iter()
1304	            .map(|instance| {
1305	                let device = if matches!(instance.device_type, Some(DeviceType::Cpu)) {
1306	                    RouteDevice::Cpu
1307	                } else {
1308	                    RouteDevice::Accelerator
1309	                };
1310	                (instance.instance_id, device)
1311	            })
1312	            .collect::<HashMap<_, _>>();
1313	        let cuda_to_cpu_ratio = std::env::var("DYN_ENCODER_CUDA_TO_CPU_RATIO")
1314	            .ok()
1315	            .and_then(|value| value.parse::<usize>().ok())
1316	            .filter(|value| *value >= 1)
1317	            .unwrap_or(8);
1318	
1319	        let (request_cache_keys, cache_matched_candidates) =
1320	            if let (Some(indexer), Some(extractor)) = (
1321	                self.multimodal_cache_indexer.as_ref(),
1322	                self.multimodal_cache_key_extractor.as_ref(),
1323	            ) {
1324	                let request_cache_keys = extractor(request);
1325	                let matched = if request_cache_keys.is_empty() {
1326	                    Vec::new()
1327	                } else {
1328	                    let mut matched = indexer.workers_with_cache_key_hits(&request_cache_keys);
1329	                    matched.retain(|(id, _)| instance_ids.contains(id));
1330	                    matched
1331	                };
1332	                (request_cache_keys, matched)
1333	            } else {
1334	                (Vec::new(), Vec::new())
1335	            };
1336	
1337	        let embedding_cache_hit = !cache_matched_candidates.is_empty();
1338	        let cache_hits = cache_matched_candidates
1339	            .into_iter()
1340	            .collect::<HashMap<_, _>>();
1341	        let request_cache_key_count = request_cache_keys
1342	            .iter()
1343	            .collect::<std::collections::HashSet<_>>()
1344	            .len();
1345	        let candidates = instance_ids
1346	            .iter()
1347	            .map(|worker_id| RouteCandidate {
1348	                target: RouteTarget::worker(*worker_id),
1349	                device: device_type_map.get(worker_id).copied().unwrap_or_default(),
1350	                cache_hits: cache_hits.get(worker_id).copied().unwrap_or_default(),
1351	            })
1352	            .collect::<Vec<_>>();
1353	
1354	        DeviceAwareCandidates {
1355	            candidates,
1356	            context: RouteContext {
1357	                required_cache_hits: request_cache_key_count,
1358	                non_cpu_to_cpu_ratio: cuda_to_cpu_ratio,
1359	            },
1360	            embedding_cache_hit,
1361	            request_cache_keys: request_cache_keys.len(),
1362	        }
1363	    }
