1408	    /// Select the next worker according to the routing mode.
1409	    /// Increments round-robin counter if applicable.
1410	    /// Returns None for modes that require request lifecycle tracking or explicit routing hints.
1411	    pub fn select_next_worker(&self) -> Option<u64> {
1412	        let routing_instances = self.client.routing_instances();
1413	        match self.router_mode {
1414	            RouterMode::RoundRobin | RouterMode::Random => self
1415	                .picker
1416	                .as_deref()?
1417	                .select(
1418	                    CandidateView::Workers(routing_instances.free_ids()),
1419	                    RouteContext::default(),
1420	                    |_| 0,
1421	                )
1422	                .map(|decision| decision.target.worker_id),
1423	            RouterMode::PowerOfTwoChoices
1424	            | RouterMode::Direct
1425	            | RouterMode::LeastLoaded
1426	            | RouterMode::DeviceAwareWeighted => None,
1427	            RouterMode::KV => {
1428	                panic!(
1429	                    "select_next_worker should not be called for {:?} routing mode",
1430	                    self.router_mode
1431	                )
1432	            }
1433	        }
1434	    }
