1436	    /// Peek the next worker according to the routing mode without incrementing the counter.
1437	    /// Useful for checking if a worker is suitable before committing to it.
1438	    ///
1439	    /// `None` for [`RouterMode::Direct`] (caller-supplied routing); panics for
1440	    /// [`RouterMode::KV`], which selects via `kv_chooser::find_best_match`.
1441	    pub fn peek_next_worker(&self) -> Option<u64> {
1442	        // Select among free (admission-eligible) workers — see select_next_worker
1443	        // for the per-mode selection rationale.
1444	        let routing_instances = self.client.routing_instances();
1445	        let instance_ids = routing_instances.free_ids();
1446	        if instance_ids.is_empty() {
1447	            return None;
1448	        }
1449	
1450	        match self.router_mode {
1451	            RouterMode::RoundRobin | RouterMode::Random => self
1452	                .picker
1453	                .as_deref()?
1454	                .peek(
1455	                    CandidateView::Workers(instance_ids),
1456	                    RouteContext::default(),
1457	                    |_| 0,
1458	                )
1459	                .map(|decision| decision.target.worker_id),
1460	            RouterMode::LeastLoaded | RouterMode::PowerOfTwoChoices => self
1461	                .occupancy_state
1462	                .as_deref()?
1463	                .peek(
1464	                    self.picker.as_deref()?,
1465	                    CandidateView::Workers(instance_ids),
1466	                    RouteContext::default(),
1467	                )
1468	                .map(|decision| decision.target.worker_id),
1469	            RouterMode::DeviceAwareWeighted => {
1470	                let state = self.occupancy_state.as_deref()?;
1471	                let device_type_map: HashMap<u64, Option<DeviceType>> = self
1472	                    .client
1473	                    .instances()
1474	                    .iter()
1475	                    .map(|instance| (instance.instance_id, instance.device_type.clone()))
1476	                    .collect();
1477	                let cuda_to_cpu_ratio = std::env::var("DYN_ENCODER_CUDA_TO_CPU_RATIO")
1478	                    .ok()
1479	                    .and_then(|value| value.parse::<usize>().ok())
1480	                    .filter(|value| *value >= 1)
1481	                    .unwrap_or(8);
1482	                let candidates = instance_ids
1483	                    .iter()
1484	                    .map(|worker_id| RouteCandidate {
1485	                        target: RouteTarget::worker(*worker_id),
1486	                        device: if matches!(
1487	                            device_type_map.get(worker_id),
1488	                            Some(Some(DeviceType::Cpu))
1489	                        ) {
1490	                            RouteDevice::Cpu
1491	                        } else {
1492	                            RouteDevice::Accelerator
1493	                        },
1494	                        cache_hits: 0,
1495	                    })
1496	                    .collect::<Vec<_>>();
1497	                state
1498	                    .peek(
1499	                        self.picker.as_deref()?,
1500	                        CandidateView::DeviceAware(&candidates),
1501	                        RouteContext {
1502	                            required_cache_hits: 0,
1503	                            non_cpu_to_cpu_ratio: cuda_to_cpu_ratio,
1504	                        },
1505	                    )
1506	                    .map(|decision| decision.target.worker_id)
1507	            }
1508	            RouterMode::Direct => None,
1509	            RouterMode::KV => {
1510	                panic!(
1511	                    "peek_next_worker should not be called for {:?} routing mode",
1512	                    self.router_mode
1513	                )
1514	            }
1515	        }
1516	    }
