1546	                }
1547	                RouterMode::RoundRobin
1548	                | RouterMode::Random
1549	                | RouterMode::Direct
1550	                | RouterMode::KV => None,
1551	            };
1552	            return Ok((instance_id, permit));
1553	        }
1554	
1555	        match self.router_mode {
1556	            RouterMode::LeastLoaded
1557	            | RouterMode::PowerOfTwoChoices
1558	            | RouterMode::DeviceAwareWeighted => {
1559	                let state = self.occupancy_state()?;
