1570	                            CandidateView::Workers(instance_ids),
1571	                            RouteContext::default(),
1572	                        )
1573	                        .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?,
1574	                    RouterMode::DeviceAwareWeighted => {
