1585	                };
1586	                let instance_id = decision.target.worker_id;
1587	                let permit = counter
1588	                    .map(|counter| OccupancyPermit::from_counter(state, instance_id, counter));
1589	                Ok((instance_id, permit))
1590	            }
1591	            RouterMode::RoundRobin => self
1592	                .select_untracked_worker(self.round_robin_picker.as_ref())
1593	                .map(|(instance_id, _)| (instance_id, None)),
1594	            RouterMode::Random => self
1595	                .select_untracked_worker(self.random_picker.as_ref())
