1636	    async fn generate_with_fault_detection_prepared<M, F>(
1637	        &self,
1638	        instance_id: u64,
1639	        mut request: SingleIn<T>,
1640	        fallback: TransportFallback<'_>,
1641	        prepare: F,
1642	    ) -> anyhow::Result<(M, ManyOut<U>)>
1643	    where
1644	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1645	    {
1646	        let route_start = Instant::now();
1647	        let request_id = request.id().to_string();
1648	        let route_span = if matches!(self.router_mode, RouterMode::KV) {
1649	            tracing::Span::none()
1650	        } else {
1651	            tracing::info_span!(
1652	                "router.route_request",
1653	                request_id = %request_id,
1654	                worker_id = instance_id,
1655	                router_mode = ?self.router_mode,
1656	            )
1657	        };
1658	
1659	        let (instance_id, address, transport_kind, instance) =
1660	            self.resolve_transport(instance_id, fallback)?;
1661	        self.check_workers_available(instance_id, &request_id)?;
1662	
1663	        let metadata = prepare(&mut request, instance_id)?;
1664	        let request = request.map(|req| AddressedRequest::with_instance(req, address, instance));
1665	
1666	        STAGE_DURATION_SECONDS
1667	            .with_label_values(&[STAGE_ROUTE])
1668	            .observe(route_start.elapsed().as_secs_f64());
1669	
1670	        let _nvtx_transport = dynamo_nvtx_range!(transport_kind);
1671	        let stream = self
1672	            .addressed
1673	            .generate(request)
1674	            .instrument(route_span)
1675	            .await;
1676	        let stream = self.wrap_with_fault_detection(stream, instance_id)?;
1677	        Ok((metadata, stream))
