1680	    /// Reject early if the selected worker is overloaded and fault detection
1681	    /// is enabled. The request_id is only used for the debug-level "checked
1682	    /// worker overload state" trace; pass an empty string from callers that
1683	    /// don't have one handy.
1684	    fn check_workers_available(&self, instance_id: u64, request_id: &str) -> anyhow::Result<()> {
1685	        if !self.fault_detection_enabled {
1686	            return Ok(());
1687	        }
1688	        let routing_instances = self.client.routing_instances();
1689	        let selected_worker_overloaded = routing_instances.is_overloaded(instance_id);
1690	        let counts = routing_instances.counts();
1691	        if tracing::enabled!(tracing::Level::DEBUG) {
1692	            tracing::debug!(
1693	                request_id,
1694	                instance_id,
1695	                router_mode = ?self.router_mode,
1696	                free_workers = counts.free,
1697	                overloaded_workers = counts.overloaded,
1698	                total_workers = counts.discovered,
1699	                selected_worker_overloaded,
1700	                "checked worker overload state"
1701	            );
1702	        }
1703	        if !selected_worker_overloaded {
1704	            return Ok(());
1705	        }
1706	        tracing::warn!(
1707	            instance_id,
1708	            overloaded_workers = counts.overloaded,
1709	            total_workers = counts.discovered,
1710	            "Rejecting request: selected worker is overloaded"
1711	        );
1712	        let cause = PipelineError::ServiceOverloaded(
1713	            "Selected worker is overloaded, please retry later".into(),
1714	        );
1715	        Err(DynamoError::builder()
1716	            .error_type(ErrorType::WorkerOverloaded)
1717	            .message("Selected worker is overloaded, please retry later")
1718	            .cause(cause)
1719	            .build()
1720	            .into())
1721	    }
1722	
1723	    /// Resolve `(instance_id, address, transport_kind_label, Instance)` for
1724	    /// the selected worker. If that worker has disappeared, apply the caller's
1725	    /// fallback policy. `CannotConnect` is returned when fallback is forbidden
1726	    /// or when a selected fallback disappears before its transport can be
1727	    /// resolved.
1728	    fn resolve_transport(
1729	        &self,
1730	        instance_id: u64,
1731	        fallback: TransportFallback<'_>,
1732	    ) -> anyhow::Result<(u64, String, &'static str, Instance)> {
1733	        use crate::component::TransportType;
1734	
1735	        let lookup = |id: u64| {
1736	            self.client
1737	                .instances()
1738	                .iter()
1739	                .find(|i| i.instance_id == id)
1740	                .map(|instance| {
1741	                    let (addr, kind) = match &instance.transport {
1742	                        TransportType::Tcp(tcp_endpoint) => {
1743	                            (tcp_endpoint.clone(), "transport.tcp.request")
1744	                        }
1745	                        TransportType::Nats(subject) => (subject.clone(), "transport.nats.request"),
1746	                    };
1747	                    (addr, kind, instance.clone())
1748	                })
1749	        };
1750	
1751	        if let Some((addr, kind, inst)) = lookup(instance_id) {
1752	            return Ok((instance_id, addr, kind, inst));
1753	        }
1754	        let allowed_fallback = match fallback {
1755	            TransportFallback::Allow => None,
1756	            TransportFallback::Deny => {
1757	                return Err(DynamoError::builder()
1758	                    .error_type(ErrorType::CannotConnect)
1759	                    .message(format!(
1760	                        "instance_id={instance_id} not found for endpoint {}",
1761	                        self.client.endpoint.id()
1762	                    ))
1763	                    .build()
1764	                    .into());
1765	            }
1766	            TransportFallback::Within(allowed) => Some(allowed),
1767	        };
1768	
1769	        let routing_instances = self.client.routing_instances();
1770	        let fallback_id = routing_instances.free_ids().iter().copied().find(|&id| {
1771	            id != instance_id && allowed_fallback.is_none_or(|allowed| allowed.contains(&id))
1772	        });
1773	        match fallback_id {
1774	            Some(id) => {
1775	                tracing::warn!(
1776	                    original_instance = instance_id,
1777	                    fallback_instance = id,
1778	                    "Instance disappeared during routing, reselecting"
1779	                );
1780	                let (addr, kind, inst) = lookup(id).ok_or_else(|| {
1781	                    DynamoError::builder()
1782	                        .error_type(ErrorType::CannotConnect)
1783	                        .message(format!(
1784	                            "Fallback instance {} also not found for endpoint {}",
1785	                            id,
1786	                            self.client.endpoint.id()
1787	                        ))
1788	                        .build()
1789	                })?;
1790	                Ok((id, addr, kind, inst))
1791	            }
1792	            // TODO(https://github.com/ai-dynamo/dynamo/issues/12383): Distinguish
1793	            // no discoverable fallback from pool-wide overload and return the
1794	            // appropriate typed error for each case.
1795	            None => Err(anyhow::anyhow!(
1796	                "Instance {} not found and no other instances available for endpoint {}",
1797	                instance_id,
1798	                self.client.endpoint.id()
1799	            )),
1800	        }
1801	    }
1802	
1803	    /// Wrap a dispatched stream with fault detection + inactivity timeout.
1804	    /// `is_inhibited` errors trigger `report_instance_down`; the timeout
1805	    /// (driven by `DYN_HTTP_BACKEND_STREAM_TIMEOUT_SECS`) yields a synthetic
1806	    /// `ResponseTimeout` and quarantines the worker.
1807	    fn wrap_with_fault_detection(
1808	        &self,
1809	        stream: anyhow::Result<ManyOut<U>>,
1810	        instance_id: u64,
1811	    ) -> anyhow::Result<ManyOut<U>> {
1812	        let stream = match stream {
1813	            Ok(stream) => stream,
1814	            Err(err) => {
1815	                if self.fault_detection_enabled {
1816	                    if is_inhibited(err.as_ref()) {
1817	                        tracing::debug!(
1818	                            "Reporting instance {instance_id} down due to error: {err}"
1819	                        );
1820	                        self.client.report_instance_down(instance_id);
1821	                    } else if match_error_chain(err.as_ref(), &[ErrorType::WorkerOverloaded], &[]) {
1822	                        // Backpressure: worker said "my queue is full,
1823	                        // retry later". Mark overloaded so this FE skips it on
1824	                        // the next selection; the next ActiveLoad event from the
1825	                        // worker monitor overwrites the overloaded set from fresh
1826	                        // metrics. This is NOT report_instance_down (fault path).
1827	                        tracing::debug!(
1828	                            "Marking instance {instance_id} overloaded due to backpressure: {err}"
1829	                        );
1830	                        self.client.mark_overloaded_immediate(instance_id);
1831	                    }
1832	                }
1833	                return Err(err);
1834	            }
1835	        };
1836	
1837	        if !self.fault_detection_enabled {
1838	            return Ok(stream);
1839	        }
1840	
1841	        let engine_ctx = stream.context();
1842	        let client = self.client.clone();
1843	        let client_for_timeout = self.client.clone();
1844	        let stream = stream.map(move |res| {
1845	            if let Some(err) = res.err()
1846	                && is_inhibited(&err)
1847	            {
1848	                tracing::debug!(
1849	                    "Reporting instance {instance_id} down due to migratable error: {err}"
1850	                );
1851	                client.report_instance_down(instance_id);
1852	            }
1853	            res
1854	        });
1855	
1856	        let stream: Pin<Box<dyn Stream<Item = U> + Send>> =
1857	            if let Some(timeout) = self.response_timeout {
1858	                Box::pin(async_stream::stream! {
1859	                    let mut inner = Box::pin(stream);
1860	                    loop {
1861	                        tokio::select! {
1862	                            biased;
1863	                            item = inner.next() => {
1864	                                match item {
1865	                                    Some(item) => yield item,
1866	                                    None => break,
1867	                                }
1868	                            }
1869	                            _ = tokio::time::sleep(timeout) => {
1870	                                tracing::warn!(
1871	                                    instance_id,
1872	                                    timeout_secs = timeout.as_secs(),
1873	                                    "backend response inactivity timeout — quarantining worker"
1874	                                );
1875	                                client_for_timeout.report_instance_down(instance_id);
1876	                                yield U::from_err(
1877	                                    crate::error::DynamoError::builder()
1878	                                        .error_type(crate::error::ErrorType::ResponseTimeout)
1879	                                        .message("backend response inactivity timeout")
1880	                                        .build()
1881	                                );
1882	                                break;
1883	                            }
1884	                        }
1885	                    }
1886	                })
1887	            } else {
1888	                Box::pin(stream)
1889	            };
1890	
1891	        Ok(ResponseStream::new(stream, engine_ctx))
1892	    }
1893	}
