1958	/// Bidirectional `AsyncEngine` impl for streaming-input workloads (e.g. the
1959	/// OpenAI Realtime API). Reserves a sticky worker up front — before any
1960	/// inbound frame is observed — and binds the whole input stream to that
1961	/// worker. KV and Direct modes inherit the same `bail!` invariants as the
1962	/// unary impl.
1963	///
1964	/// **Reserve-before-observe rationale.** The router-mode strategies
1965	/// (`RoundRobin`, `Random`, `PowerOfTwoChoices`, `LeastLoaded`,
1966	/// `DeviceAwareWeighted`) don't depend on frame contents, so selection
1967	/// runs immediately and connection setup proceeds in parallel with the
1968	/// client producing its first frame. A client that connects but never
1969	/// sends one still releases the slot via the response-stream-drop path;
1970	/// the dispatch-side `cancel_both` cleanup covers the early-bail case.
1971	#[async_trait]
1972	impl<T, U> AsyncEngine<ManyIn<T>, ManyOut<U>, Error> for PushRouter<T, U>
1973	where
1974	    T: Data + Serialize,
1975	    U: Data + for<'de> Deserialize<'de> + MaybeError,
1976	{
1977	    async fn generate(&self, input: ManyIn<T>) -> Result<ManyOut<U>, Error> {
1978	        match self.router_mode {
1979	            RouterMode::KV => {
1980	                anyhow::bail!("KV routing should not call generate on PushRouter");
1981	            }
1982	            RouterMode::Direct => {
1983	                anyhow::bail!(
1984	                    "Direct routing should not call generate on PushRouter directly; use RoutingHost"
1985	                );
1986	            }
1987	            // These modes drive `select_next_worker()` to `None` — they rely on
1988	            // the occupancy/load-aware selection the bidirectional path does not
1989	            // wire yet, which would otherwise surface as a misleading "no
1990	            // instances available" error below. Reject them explicitly until
1991	            // bidirectional support lands; tracked in
1992	            // https://github.com/ai-dynamo/dynamo/issues/10320.
1993	            RouterMode::PowerOfTwoChoices
1994	            | RouterMode::LeastLoaded
1995	            | RouterMode::DeviceAwareWeighted => {
1996	                anyhow::bail!(
1997	                    "{:?} routing is not yet supported for bidirectional dispatch",
1998	                    self.router_mode
1999	                );
2000	            }
2001	            RouterMode::RoundRobin | RouterMode::Random => {}
2002	        }
2003	
2004	        let instance_id = self
2005	            .select_next_worker()
2006	            .ok_or_else(|| anyhow::anyhow!("no instances available for bidirectional routing"))?;
2007	
2008	        self.bidirectional_dispatch(instance_id, input).await
2009	    }
2010	}
